using Json=nlohmann::json;
bool number(const char* label,Json& v){double n=v.get<double>();if(!ImGui::InputDouble(label,&n,0,0,"%.3f"))return false;v=n;return true;}
bool integer(const char* label,Json& v){int n=v.get<int>();if(!ImGui::InputInt(label,&n))return false;v=n;return true;}
void tick_field(const char* label,Json& value){double tick=value.get<double>()/action_tick_units;if(ImGui::InputDouble(label,&tick)){if(!std::isfinite(tick)||tick<0||tick>600)throw std::runtime_error("Use a finite tick between 0 and 600");value=static_cast<unsigned>(std::llround(tick*action_tick_units));}}
void flag(const char* label,Json& v){bool n=v.get<bool>();if(ImGui::Checkbox(label,&n))v=n;}
void choice(const char* label,Json& v,std::initializer_list<const char*> choices){auto name=v.get<std::string>();if(ImGui::BeginCombo(label,name.c_str())){for(auto c:choices)if(ImGui::Selectable(c,name==c))v=c;ImGui::EndCombo();}}
void text(const char* label,Json& v){char buffer[129]{};auto s=v.get<std::string>();strncpy_s(buffer,s.c_str(),_TRUNCATE);if(ImGui::InputText(label,buffer,sizeof(buffer)))v=buffer;}
Json schema(Controller& c,const Json& v,const char* key){
 if(std::string_view(key)=="tags"&&v.contains("tag_source")){auto id=AssetId::parse(v.at("tags").get<std::string>());const auto& value=c.authoring.open(*c.assets,id).value;decode_tag_asset(value.dump());return value.at("tags");}
 if(!v.contains("sources")||!v["sources"].contains(key))return Json::array();auto path=v["sources"][key].get<std::string>();
 for(const auto& asset:c.asset_inventory)if(asset.path==path){auto draft=c.authoring.drafts.find(asset.id);if(draft!=c.authoring.drafts.end())return draft->second.value.at(key);}
 std::ifstream file(c.assets->source_root()/path);return Json::parse(file).at(key);
}
void ids(const char* label,Json& list,const Json& definitions){if(ImGui::TreeNode(label)){for(const auto& d:definitions){auto id=d["id"];auto it=std::find(list.begin(),list.end(),id);bool selected=it!=list.end();if(ImGui::Checkbox(d["name"].get<std::string>().c_str(),&selected)){if(selected)list.push_back(id);else list.erase(it);}}ImGui::TreePop();}}
void attribute(const char* label,Json& value,const Json& defs,bool resource_only=false,bool statistic_only=false){
 std::string current="Choose attribute";bool compatible=false;
 for(const auto& d:defs)if(d["id"]==value){current=d["name"];compatible=selectable_attribute(d,resource_only)&&(!statistic_only||d.at("kind")=="statistic");}
 if(!compatible)current+=" (invalid selection)";
 if(ImGui::BeginCombo(label,current.c_str())){
  for(const auto& d:defs)if(selectable_attribute(d,resource_only)&&(!statistic_only||d.at("kind")=="statistic")){ImGui::PushID(d["id"].get<int>());if(ImGui::Selectable(d["name"].get<std::string>().c_str(),d["id"]==value))value=d["id"];ImGui::PopID();}
  ImGui::EndCombo();
 }
}
bool picker(const char* label,AssetId& selected,Controller& c,std::map<std::uint32_t,std::array<char,128>>& filters,const char* extension,const Json* attributes=nullptr,const char* importer="clip-gltf-v1",bool looping_only=false){
 std::string name=selected==AssetId{}?"Choose asset":"Missing asset";
 const AssetInfo* selected_info=nullptr;for(const auto& a:c.asset_inventory)if(a.id==selected){name=a.path;selected_info=&a;}
 bool changed=false;auto& query=filters[ImHashStr((std::string(extension)+"/"+label).c_str())];
 ImGui::PushID(label);ImGui::TextUnformatted(label);ImGui::SetNextItemWidth(-1.f);
 auto display=selected==AssetId{}||name=="Missing asset"?name:std::filesystem::path(name).filename().string();
 auto selected_draft=c.authoring.drafts.find(selected);if(selected_draft!=c.authoring.drafts.end()&&selected_draft->second.pending)display+=" (new)";
 if(ImGui::BeginCombo("##asset-reference",display.c_str())){
  ImGui::InputTextWithHint("##reference-search","Search path or UUID...",query.data(),query.size());ImGui::SameLine();if(ImGui::SmallButton("Clear"))query.fill(0);
  auto candidates=reference_candidates(*c.assets,c.authoring,c.asset_inventory,extension,query.data(),attributes,importer,looping_only);
  if(candidates.empty())ImGui::TextDisabled("No compatible references match.");
  ImGui::BeginChild("##reference-results",{0,240});
  for(const auto& candidate:candidates){const auto& a=candidate.asset;ImGui::PushID(a.id.text().c_str());ImGui::BeginDisabled(!candidate.diagnostic.empty());
   if(ImGui::Selectable(a.path.c_str(),selected==a.id)){selected=a.id;changed=true;}
   ImGui::EndDisabled();
   if(ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled)){ImGui::BeginTooltip();ImGui::TextUnformatted(a.path.c_str());ImGui::Text("UUID: %s",a.id.text().c_str());auto pending=c.authoring.drafts.find(a.id);if(pending!=c.authoring.drafts.end()&&pending->second.pending)ImGui::TextUnformatted("Pending creation; not published");else ImGui::Text("Catalog generation: %llu",static_cast<unsigned long long>(a.generation));if(!candidate.diagnostic.empty())ImGui::TextWrapped("Unavailable: %s",candidate.diagnostic.c_str());else ImGui::TextUnformatted("Final compatibility is validated by native cook/preparation.");ImGui::EndTooltip();}
   ImGui::PopID();
  }ImGui::EndChild();ImGui::EndCombo();
 }if(ImGui::IsItemHovered()){ImGui::BeginTooltip();ImGui::TextWrapped("%s",name.c_str());ImGui::Text("UUID: %s",selected.text().c_str());if(selected_info){auto pending=c.authoring.drafts.find(selected);if(pending!=c.authoring.drafts.end()&&pending->second.pending)ImGui::TextUnformatted("Pending creation; not published");else {ImGui::Text("Catalog generation: %llu",static_cast<unsigned long long>(selected_info->generation));if(pending!=c.authoring.drafts.end()&&pending->second.dirty())ImGui::TextWrapped("Edited draft; frozen gameplay remains unchanged until validated Save and fresh Play.");}auto checked=reference_candidates(*c.assets,c.authoring,std::span<const AssetInfo>(selected_info,1),extension,"",attributes,importer,looping_only);if(checked.empty())ImGui::TextWrapped("Unavailable here: does not match the required asset type, attribute schema or clip policy.");else if(!checked.front().diagnostic.empty())ImGui::TextWrapped("Unavailable: %s",checked.front().diagnostic.c_str());else ImGui::TextUnformatted("Picker policy matches; native Save/preview validation still applies.");}ImGui::EndTooltip();}ImGui::PopID();return changed;
}
